/* raisetrace: C library for generating stack traces on fault/signal
 * (https://github.com/deimonn/raisetrace) */

#ifndef _RAISETRACE_H
#define _RAISETRACE_H

struct backtrace_state;

/* List of signals generated by severe program faults. */
extern const int raisetrace_faults[];

/* List of signals generated by sockets, timers or by the user. */
extern const int raisetrace_unhandled[];

/* If set, will be called by the handler installed by raisetrace() when a signal
 * is caught.
 *
 * Receives the signal number as the first parameter, a message describing the
 * signal as the second, and raisetrace's backtrace_state as the third.
 *
 * Note that returning from this function simply returns from the signal
 * handler; it is up to the callee to kill the thread or program for
 * non-continuable signals. */
extern void (*raisetrace_callback)(int num, const char *msg,
                                   struct backtrace_state *state);

/* Install raisetrace's handler for each of the specified signals.
 *
 * The handler simply calls raisetrace_callback() if it is not NULL; otherwise,
 * it prints a message and a stack trace (when supported) to the standard error
 * stream and then performs the default action for the signal.
 *
 * The siglist array must be zero-terminated.
 *
 * Returns 0 on success, a negative error number on failure. */
int raisetrace(const int *siglist);

#endif
